import type { ReactNode, SVGProps } from "react";

export interface AssetProps extends Omit<SVGProps<SVGSVGElement>, "width" | "height"> {
  /** Lebar dalam px (angka) atau satuan CSS (string). Tinggi mengikuti rasio asli. */
  size?: number | string;
  className?: string;
}

function Base({ size = 120, vb, label, className, children, ...rest }: AssetProps & { vb: [number, number]; label: string; children: ReactNode }) {
  const height = typeof size === "number" ? (size * vb[1]) / vb[0] : `calc(${size} * ${vb[1] / vb[0]})`;
  return (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox={`0 0 ${vb[0]} ${vb[1]}`} width={size} height={height} className={className} role="img" aria-label={label} {...rest}>
      {children}
    </svg>
  );
}

